import{_ as l,o as t,c as a,a3 as e}from"./chunks/framework.D8u9WiMi.js";const m=JSON.parse('{"title":"11号的流水账","description":"","frontmatter":{},"headers":[],"relativePath":"listOfEvents/2026/march/11.md","filePath":"listOfEvents/2026/march/11.md"}'),s={name:"listOfEvents/2026/march/11.md"};function p(n,i,r,o,h,d){return t(),a("div",null,[...i[0]||(i[0]=[e('<h1 id="_11号的流水账" tabindex="-1">11号的流水账 <a class="header-anchor" href="#_11号的流水账" aria-label="Permalink to &quot;11号的流水账&quot;">​</a></h1><p>今天还是主要看黑马的java笔记</p><ol><li><p>ChronoUnit 一个枚举类型，包含了所有可能的时间间隔，并且开业执行一些简单的算术运算，因为枚举我好像到这里的时候还没学，所以大概跳过了</p></li><li><p>Concurrent类，一个管理线程池的类</p><ol><li>创建一个有固定线程数量的线程池</li><li>创建一个根据需要自动调整线程数量的线程池</li><li>创建只有单个线程的线程池</li></ol></li><li><p>中级剩下的算是终于过完了，有单担心，感觉有点被坑了，看的java视频时长有点短，删了好多东西，只能走一步看一步了</p></li><li><p>只是加油站内容，看看今天还有时间，把知识加油站的东西单领出来，变成单独md文件，二级</p></li><li><p>成员变量和局部变量的区别</p><ol><li>成员变量定义在方法外，局部在方法内</li><li>成员在堆中，局部在栈里</li><li>声明周期不同，局部跟随方法，成员跟随类</li><li>初始化不同，成员可以写默认值，局部不能写默认值---但在java21中好像可以了</li></ol></li><li><p>DateTimeFormatter和SimpleDateFormat的区别</p><ol><li>SimpleDateFormat是8之前的，多线程有问题，性能也不好，支持的格式化选项少</li><li>DateTimeFormatter是8加入的，可以多线程，性能也比较好，支持的格式化格式更多</li></ol></li><li><p>java键盘录入</p><ol><li>除nextLine外的next会被空格解析停止，空格后面的当前的next输入就不接收了，但还是会存储在内存中，会被后面的next接受</li><li>注意和nextLine的混用问题，回车也会被next当做输入直接接收</li></ol></li><li><p>Java内存模型</p><ol><li>栈内存为方法提供使用、堆内存为对象提供使用、方法区为执行的class文件临时存储</li></ol></li><li><p>idea快捷键</p><ol><li>ctrl+alt+b:选中一个方法，按下即可查看此接口的实现类</li><li>ctrl+f12可以查看当前类中的状态，例如成员方法，成员属性等</li></ol></li><li><p>int和Integer的区别</p><ol><li>int是个数据类型，integer是int的包装类，里面有方法</li></ol></li><li><p>string和character</p><ol><li>string是类，character是字符的包装类</li></ol></li><li><p>ArrayList是个数据集合类，有点像js里的数组，默认可以放任何类型的数据，不是只能放单一类型的数据。</p><ol><li><p>add 直接添加到末尾和添加到指定索引，返回boolean</p></li><li><p>remove 直接查找删除和删除指定索引上的元素</p></li><li><p>get获取指定索引的元素</p></li><li><p>set 修改指定位置索引的元素，有就替换，没有就添加</p></li><li><p>size 获取数据集合的长度</p></li><li><p>indexOf 可以查找第一次出现的索引</p></li><li><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ArrayList&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; list </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ArrayList&lt;&gt;	</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 只能添加string类型的数据了，&lt;类型&gt;	&lt;E&gt;表示泛型</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol></li></ol>',3)])])}const k=l(s,[["render",p]]);export{m as __pageData,k as default};
